public InventFiscalLIFOGroup performLookup(FormStringControl _formStringControl)
{
    Args args = new Args();
    args.name(formStr(GUPInventFiscalLIFOGroupLookup));
    args.caller(this);

    args.parmObject(this);
    args.lookupField(fieldNum(InventFiscalLIFOGroup, RecId));
    args.lookupValue(_formStringControl.valueStr());

    FormRun formRun = classfactory.formRunClass(args);
    formRun.init();

    _formStringControl.performFormLookup(formRun);
    InventFiscalLIFOGroup inventFiscalLIFOGroup = formRun.selectRecordModeSelectedRecord() as InventFiscalLIFOGroup;

    return inventFiscalLIFOGroup;
}

public static GUPInventFiscalLIFOGroupLookup construct(boolean _returnRefRecID)
{
